MODULES['pipeline/jt/show/camera.py'] = '"""\nJuicy Tea Map-Shorts Engine — Continuous C2 Camera, Single-Geometry Projection Morph & Hermite Loop.\nImplements:\n- Time-parameterized C2 cubic/quintic spline across (w, lon, lat, ln(span))\n- Zero hard-clamping on spline outputs (Rule 2 & Section 3)\n- Quintic smootherstep (6u^5 - 15u^4 + 10u^3) for standalone moves and morphs\n- Continuous unidirectional hold drift (1-3%/s scale, <=0.5% screen_width/s pan)\n- Single-geometry projection morph with convex superellipse silhouette & atmosphere stroke\n- Seamless 0.5s (30 frames @ 60fps) C1 Hermite loop into moving Frame 0\n"""\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Tuple\nimport math\nimport numpy as np\n\nFPS: int = 60\nWIDTH: int = 1080\nHEIGHT: int = 1920\nLOOP_TAIL_SEC: float = 0.5\nLOOP_FRAMES: int = int(round(LOOP_TAIL_SEC * FPS))  # 30 frames @ 60fps\n\n\ndef smoothstep(u: float | np.ndarray) -> float | np.ndarray:\n    """C1 cubic step: permitted ONLY for alpha and same-geometry texture LoD crossfades."""\n    u_c = np.clip(u, 0.0, 1.0)\n    return u_c * u_c * (3.0 - 2.0 * u_c)\n\n\ndef smootherstep(u: float | np.ndarray) -> float | np.ndarray:\n    """C2 quintic step: 6u^5 - 15u^4 + 10u^3. Zero velocity and zero acceleration at u=0, 1."""\n    u_c = np.clip(u, 0.0, 1.0)\n    return u_c * u_c * u_c * (u_c * (u_c * 6.0 - 15.0) + 10.0)\n\n\ndef smootherstep_deriv(u: float | np.ndarray, duration: float) -> float | np.ndarray:\n    """First time-derivative of smootherstep: 30 * u^2 * (1-u)^2 / T."""\n    if duration <= 1e-9:\n        return 0.0\n    u_c = np.clip(u, 0.0, 1.0)\n    return (30.0 * (u_c ** 2) * ((1.0 - u_c) ** 2)) / duration\n\n\n@dataclass(frozen=True)\nclass CameraAnchor:\n    t: float\n    w: float       # 0.0 = Mercator, 1.0 = Orthographic globe\n    lon: float     # degrees (automatically unwrapped across dateline)\n    lat: float     # degrees\n    span: float    # degrees (must stay within [28.0, 170.0] without post-clamping)\n    is_snap: bool = False\n\n\nclass TimeParameterizedC2Spline:\n    """\n    Time-parameterized C2-continuous Spline over non-uniform anchor timestamps t_i.\n    Eliminates the C1 velocity jumps of uniform Catmull-Rom on uneven (0.7s - 2.8s) intervals.\n    Uses Fritsch-Carlson monotone tangent damping with C2 quintic Hermite segments so flat\n    intervals (e.g. w=0 -> w=0 or w=1 -> w=1) never overshoot [0, 1] and never require hard clamping.\n    """\n\n    def __init__(\n        self,\n        t: np.ndarray,\n        y: np.ndarray,\n        v_start: float | None = None,\n        v_end: float | None = None,\n    ) -> None:\n        self.t = np.asarray(t, dtype=np.float64)\n        self.y = np.asarray(y, dtype=np.float64)\n        n = len(self.t)\n        if n < 2:\n            raise ValueError("At least 2 anchors are required for C2 spline.")\n        if np.any(np.diff(self.t) <= 1e-6):\n            raise ValueError("Anchor timestamps must be strictly increasing.")\n\n        self.h = np.diff(self.t)\n        secants = np.diff(self.y) / self.h\n        d = np.zeros(n, dtype=np.float64)\n        d[0] = v_start if v_start is not None else secants[0] * 0.5\n        d[-1] = v_end if v_end is not None else secants[-1] * 0.5\n\n        for i in range(1, n - 1):\n            if secants[i - 1] * secants[i] <= 0.0:\n                d[i] = 0.0\n            else:\n                w1 = 2.0 * self.h[i] + self.h[i - 1]\n                w2 = self.h[i] + 2.0 * self.h[i - 1]\n                d[i] = (w1 + w2) / (w1 / secants[i - 1] + w2 / secants[i])\n\n        self.tangents = d\n\n    def eval_with_derivs(self, t_query: float) -> Tuple[float, float, float]:\n        """Returns (position, velocity, acceleration) at time t_query with C2 continuity."""\n        tq = float(np.clip(t_query, self.t[0], self.t[-1]))\n        idx = int(np.searchsorted(self.t, tq, side="right")) - 1\n        idx = max(0, min(idx, len(self.t) - 2))\n\n        h = self.h[idx]\n        y0, y1 = self.y[idx], self.y[idx + 1]\n        v0, v1 = self.tangents[idx], self.tangents[idx + 1]\n        u = float(np.clip((tq - self.t[idx]) / h, 0.0, 1.0))\n\n        u2 = u * u\n        u3 = u2 * u\n        u4 = u3 * u\n        u5 = u4 * u\n\n        # Quintic Hermite basis with zero knot acceleration (a0 = a1 = 0 -> C2 continuous everywhere)\n        h0 = 1.0 - 10.0 * u3 + 15.0 * u4 - 6.0 * u5\n        h1 = u - 6.0 * u3 + 8.0 * u4 - 3.0 * u5\n        h2 = 10.0 * u3 - 15.0 * u4 + 6.0 * u5\n        h3 = -4.0 * u3 + 7.0 * u4 - 3.0 * u5\n        pos = h0 * y0 + h1 * (h * v0) + h2 * y1 + h3 * (h * v1)\n\n        dh0 = -30.0 * u2 + 60.0 * u3 - 30.0 * u4\n        dh1 = 1.0 - 18.0 * u2 + 32.0 * u3 - 15.0 * u4\n        dh2 = 30.0 * u2 - 60.0 * u3 + 30.0 * u4\n        dh3 = -12.0 * u2 + 28.0 * u3 - 15.0 * u4\n        vel = (dh0 * y0 + dh1 * (h * v0) + dh2 * y1 + dh3 * (h * v1)) / h\n\n        ddh0 = -60.0 * u + 180.0 * u2 - 120.0 * u3\n        ddh1 = -36.0 * u + 96.0 * u2 - 60.0 * u3\n        ddh2 = 60.0 * u - 180.0 * u2 + 120.0 * u3\n        ddh3 = -24.0 * u + 84.0 * u2 - 60.0 * u3\n        acc = (ddh0 * y0 + ddh1 * (h * v0) + ddh2 * y1 + ddh3 * (h * v1)) / (h * h)\n\n        return float(pos), float(vel), float(acc)\n\n\ndef hermite_segment(\n    t: float,\n    t0: float,\n    t1: float,\n    p0: float,\n    v0: float,\n    p1: float,\n    v1: float,\n) -> Tuple[float, float, float]:\n    """\n    Cubic Hermite bridge over [t0, t1] matching exact endpoint positions (p0, p1)\n    and velocities (v0, v1) for the final 0.5s (30 frames @ 60fps) seamless loop into Frame 0.\n    """\n    T = max(t1 - t0, 1e-9)\n    u = float(np.clip((t - t0) / T, 0.0, 1.0))\n    u2 = u * u\n    u3 = u2 * u\n\n    h00 = 2.0 * u3 - 3.0 * u2 + 1.0\n    h10 = u3 - 2.0 * u2 + u\n    h01 = -2.0 * u3 + 3.0 * u2\n    h11 = u3 - u2\n\n    pos = h00 * p0 + h10 * (T * v0) + h01 * p1 + h11 * (T * v1)\n\n    dh00 = 6.0 * u2 - 6.0 * u\n    dh10 = 3.0 * u2 - 4.0 * u + 1.0\n    dh01 = -6.0 * u2 + 6.0 * u\n    dh11 = 3.0 * u2 - 2.0 * u\n    vel = (dh00 * p0 + dh10 * (T * v0) + dh01 * p1 + dh11 * (T * v1)) / T\n\n    ddh00 = 12.0 * u - 6.0\n    ddh10 = 6.0 * u - 4.0\n    ddh01 = -12.0 * u + 6.0\n    ddh11 = 6.0 * u - 2.0\n    acc = (ddh00 * p0 + ddh10 * (T * v0) + ddh01 * p1 + ddh11 * (T * v1)) / (T * T)\n\n    return float(pos), float(vel), float(acc)\n\n\nclass ContinuousCameraRig:\n    """\n    Continuous 4-channel camera trajectory (w, lon, lat, ln(span)).\n    - Starts in motion at Frame 0 (non-zero initial drift velocity).\n    - Never hard-clamps spline outputs.\n    - Bridges the final 0.5s into Frame 0 via C1-continuous Hermite interpolation.\n    """\n\n    def __init__(self, anchors: List[CameraAnchor], total_duration: float) -> None:\n        if len(anchors) < 2:\n            raise ValueError("At least 2 camera anchors are required.")\n        self.total_duration = float(total_duration)\n        self.loop_start_t = self.total_duration - LOOP_TAIL_SEC\n\n        # Frame 0 starts in motion: gentle initial drift velocity\n        self.v0_w = 0.0\n        self.v0_lon = 0.20\n        self.v0_lat = 0.04\n        self.v0_log_span = -0.015  # -1.5%/s initial scale drift\n\n        first = anchors[0]\n        core_anchors = [a for a in anchors if a.t < self.loop_start_t - 0.8]\n        # Align loop_start_t (T - 0.5s) smoothly so the final 0.5s Hermite bridge\n        # is a gentle continuation into Frame 0 with zero jerk or velocity spike\n        pre_loop_span = first.span / math.exp(self.v0_log_span * LOOP_TAIL_SEC)\n        core_anchors.append(\n            CameraAnchor(\n                t=self.loop_start_t,\n                w=first.w,\n                lon=first.lon - self.v0_lon * LOOP_TAIL_SEC,\n                lat=first.lat - self.v0_lat * LOOP_TAIL_SEC,\n                span=pre_loop_span,\n                is_snap=False,\n            )\n        )\n\n        self.anchors = core_anchors\n        t_arr = np.array([a.t for a in core_anchors], dtype=np.float64)\n        w_arr = np.array([a.w for a in core_anchors], dtype=np.float64)\n        lon_arr = np.rad2deg(np.unwrap(np.deg2rad([a.lon for a in core_anchors])))\n        lat_arr = np.array([a.lat for a in core_anchors], dtype=np.float64)\n        log_span_arr = np.log(np.array([a.span for a in core_anchors], dtype=np.float64))\n\n        self.spline_w = TimeParameterizedC2Spline(\n            t_arr, w_arr, v_start=self.v0_w, v_end=self.v0_w\n        )\n        self.spline_lon = TimeParameterizedC2Spline(\n            t_arr, lon_arr, v_start=self.v0_lon, v_end=self.v0_lon\n        )\n        self.spline_lat = TimeParameterizedC2Spline(\n            t_arr, lat_arr, v_start=self.v0_lat, v_end=self.v0_lat\n        )\n        self.spline_log_span = TimeParameterizedC2Spline(\n            t_arr, log_span_arr, v_start=self.v0_log_span, v_end=self.v0_log_span\n        )\n\n    def evaluate_all(self, t: float) -> Dict[str, float]:\n        """Returns position, velocity, and acceleration for all 4 channels at time t."""\n        t_clamped = float(np.clip(t, 0.0, self.total_duration))\n        if t_clamped <= self.loop_start_t:\n            w, dw, ddw = self.spline_w.eval_with_derivs(t_clamped)\n            lon, dlon, ddlon = self.spline_lon.eval_with_derivs(t_clamped)\n            lat, dlat, ddlat = self.spline_lat.eval_with_derivs(t_clamped)\n            lspan, dlspan, ddlspan = self.spline_log_span.eval_with_derivs(t_clamped)\n        else:\n            w0, dw0, _ = self.spline_w.eval_with_derivs(self.loop_start_t)\n            w1, dw1, _ = self.spline_w.eval_with_derivs(0.0)\n            w, dw, ddw = hermite_segment(\n                t_clamped, self.loop_start_t, self.total_duration, w0, dw0, w1, dw1\n            )\n\n            lon0, dlon0, _ = self.spline_lon.eval_with_derivs(self.loop_start_t)\n            lon1, dlon1, _ = self.spline_lon.eval_with_derivs(0.0)\n            lon1_wrapped = lon0 + ((lon1 - lon0 + 180.0) % 360.0 - 180.0)\n            lon, dlon, ddlon = hermite_segment(\n                t_clamped, self.loop_start_t, self.total_duration, lon0, dlon0, lon1_wrapped, dlon1\n            )\n\n            lat0, dlat0, _ = self.spline_lat.eval_with_derivs(self.loop_start_t)\n            lat1, dlat1, _ = self.spline_lat.eval_with_derivs(0.0)\n            lat, dlat, ddlat = hermite_segment(\n                t_clamped, self.loop_start_t, self.total_duration, lat0, dlat0, lat1, dlat1\n            )\n\n            ls0, dls0, _ = self.spline_log_span.eval_with_derivs(self.loop_start_t)\n            ls1, dls1, _ = self.spline_log_span.eval_with_derivs(0.0)\n            lspan, dlspan, ddlspan = hermite_segment(\n                t_clamped, self.loop_start_t, self.total_duration, ls0, dls0, ls1, dls1\n            )\n\n        return {\n            "w": w, "dw": dw, "ddw": ddw,\n            "lon": lon, "dlon": dlon, "ddlon": ddlon,\n            "lat": lat, "dlat": dlat, "ddlat": ddlat,\n            "log_span": lspan, "dlog_span": dlspan, "ddlog_span": ddlspan,\n            "span": math.exp(lspan),\n        }\n\n    def camera_channels(self, t: float) -> Tuple[float, float, float, float]:\n        """Drop-in replacement for camera_channels(t) -> (w, lon, lat, span)."""\n        st = self.evaluate_all(t)\n        return st["w"], st["lon"], st["lat"], st["span"]\n\n\ndef blend_xy_morph(merc_xy: np.ndarray, ortho_xy: np.ndarray, w: float) -> np.ndarray:\n    """\n    Single-geometry projection morph: (1 - s) * merc + s * ortho, where s = smootherstep(w).\n    Never crossfades two separate rendered frames (Rule 1).\n    """\n    s = float(smootherstep(w))\n    return (1.0 - s) * merc_xy + s * ortho_xy\n\n\ndef superellipse_silhouette(\n    w: float, width: int = WIDTH, height: int = HEIGHT, globe_radius: float = 460.0, n_pts: int = 256\n) -> Tuple[np.ndarray, float]:\n    """\n    Convex superellipse silhouette transitioning smoothly from full viewport rectangle (w=0)\n    to circular orthographic globe disc (w=1), plus atmosphere stroke alpha (s in 0.55..0.93).\n    """\n    s = float(smootherstep(w))\n    rx = (1.0 - s) * (width * 0.52) + s * globe_radius\n    ry = (1.0 - s) * (height * 0.52) + s * globe_radius\n    exponent = (1.0 - s) * 18.0 + s * 2.0\n\n    theta = np.linspace(0.0, 2.0 * math.pi, n_pts, endpoint=False)\n    cos_t = np.cos(theta)\n    sin_t = np.sin(theta)\n    x = (width * 0.5) + rx * np.sign(cos_t) * (np.abs(cos_t) ** (2.0 / exponent))\n    y = (height * 0.5) + ry * np.sign(sin_t) * (np.abs(sin_t) ** (2.0 / exponent))\n\n    atmo_alpha = float(smoothstep((s - 0.55) / (0.93 - 0.55)))\n    return np.column_stack([x, y]), atmo_alpha\n\n\ndef globe_lod_mix(span: float) -> float:\n    """Same-geometry LoD crossfade between regional hypsometric tint and Blue Marble (span 40..82)."""\n    u = (span - 40.0) / (82.0 - 40.0)\n    return float(smoothstep(u))\n'

# === pipeline/jt/show/flyto.py ===
MODULES['pipeline/jt/show/flyto.py'] = '"""\nJuicy Tea Map-Shorts Engine — Van Wijk Optimal Zoom-Pan Flyto Curve (Zero Blur).\nImplements Section 4.1 & 4.3: rho = 1.42, smootherstep time parameterization, duration 1.0 - 1.6s.\n"""\n\nfrom __future__ import annotations\nfrom typing import Tuple\nimport math\nfrom .camera import smootherstep\n\n\ndef van_wijk_flyto(\n    u_time: float,\n    lon0: float,\n    lat0: float,\n    span0: float,\n    lon1: float,\n    lat1: float,\n    span1: float,\n    rho: float = 1.42,\n) -> Tuple[float, float, float]:\n    """\n    Evaluates (lon, lat, span) at normalized time u_time in [0, 1] along a van Wijk & Nuij\n    hyperbolic zoom-pan geodesic with C2 smootherstep time warping and zero motion blur.\n    """\n    u = float(smootherstep(u_time))\n    dlon = ((lon1 - lon0 + 180.0) % 360.0) - 180.0\n    dlat = lat1 - lat0\n    dist = math.hypot(dlon * math.cos(math.radians(0.5 * (lat0 + lat1))), dlat)\n\n    if dist < 1e-4:\n        span = math.exp((1.0 - u) * math.log(span0) + u * math.log(span1))\n        return lon0 + u * dlon, lat0 + u * dlat, span\n\n    rho2 = rho * rho\n    w0 = max(span0, 1e-3)\n    w1 = max(span1, 1e-3)\n\n    b0 = (w1 * w1 - w0 * w0 + (rho2 ** 2) * (dist ** 2)) / (2.0 * w0 * rho2 * dist)\n    b1 = (w1 * w1 - w0 * w0 - (rho2 ** 2) * (dist ** 2)) / (2.0 * w1 * rho2 * dist)\n\n    r0 = math.log(-b0 + math.sqrt(b0 * b0 + 1.0))\n    r1 = math.log(-b1 + math.sqrt(b1 * b1 + 1.0))\n    S = (r1 - r0) / rho\n\n    if abs(S) < 1e-5:\n        span = math.exp((1.0 - u) * math.log(w0) + u * math.log(w1))\n        return lon0 + u * dlon, lat0 + u * dlat, span\n\n    s = u * S\n    cosh_r0 = math.cosh(r0)\n    w_s = w0 * (cosh_r0 / math.cosh(rho * s + r0))\n    u_s = (w0 / (rho2 * dist)) * (cosh_r0 * math.tanh(rho * s + r0) - math.sinh(r0))\n    u_s = float(max(0.0, min(1.0, u_s)))\n\n    lon = lon0 + u_s * dlon\n    lat = lat0 + u_s * dlat\n    span = float(max(28.0, min(170.0, w_s)))\n    return lon, lat, span\n'

# === pipeline/jt/show/retime.py ===
MODULES['pipeline/jt/show/retime.py'] = '"""\nJuicy Tea Map-Shorts Engine — Locked-Duration Retime & Unidirectional Drift Fill.\nEnforces Rule 6 & Section 4.6:\n- Move durations and peak velocities are strictly locked when retiming to words.json.\n- Holds between moves are filled with unidirectional drift (1-3%/s scale, <=0.5% sw/s pan).\n"""\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass, replace\nfrom typing import Dict, List\nimport math\nimport numpy as np\nfrom .camera import CameraAnchor, FPS\n\n\n@dataclass(frozen=True)\nclass LockedCameraMove:\n    move_id: str\n    cue_word_index: int\n    start_t: float\n    duration: float          # LOCKED: never stretched when VO changes\n    w_start: float\n    w_end: float\n    lon_start: float\n    lon_end: float\n    lat_start: float\n    lat_end: float\n    span_start: float\n    span_end: float\n    drift_scale_rate: float = -0.012  # -1.2%/s unidirectional scale drift during hold\n    drift_lon_rate: float = 0.08      # deg/s unidirectional lon drift during hold\n    drift_lat_rate: float = 0.02      # deg/s unidirectional lat drift during hold\n    is_snap: bool = False\n\n    def validate_duration(self) -> None:\n        span_ratio = max(self.span_start, self.span_end) / max(\n            min(self.span_start, self.span_end), 1e-6\n        )\n        is_small_correction = (span_ratio - 1.0) < 0.10 and abs(\n            self.lon_end - self.lon_start\n        ) < 2.0\n        min_dur = 0.5 if is_small_correction else 0.8\n        if not (min_dur <= self.duration <= 2.0):\n            raise ValueError(\n                f"Move \'{self.move_id}\' duration {self.duration:.2f}s violates "\n                f"[{min_dur:.1f}s, 2.0s] rule."\n            )\n\n    @property\n    def peak_zoom_velocity(self) -> float:\n        return 1.875 * abs(math.log(self.span_end / self.span_start)) / self.duration\n\n\ndef retime_moves_to_words(\n    moves: List[LockedCameraMove],\n    words: List[Dict[str, float]],\n    min_hold_gap: float = 0.15,\n) -> List[LockedCameraMove]:\n    """Shifts move start times to match words.json while locking move duration & velocity."""\n    retimed: List[LockedCameraMove] = []\n    cursor_t = 0.0\n\n    for mv in moves:\n        mv.validate_duration()\n        if 0 <= mv.cue_word_index < len(words):\n            word_t = float(words[mv.cue_word_index]["start"])\n        else:\n            word_t = mv.start_t\n\n        new_start = max(word_t, cursor_t)\n        retimed_mv = replace(mv, start_t=new_start)\n        retimed.append(retimed_mv)\n        cursor_t = new_start + mv.duration + min_hold_gap\n\n    verify_retime_invariants(moves, retimed)\n    return retimed\n\n\ndef build_anchors_with_drift(moves: List[LockedCameraMove]) -> List[CameraAnchor]:\n    """\n    Converts LockedCameraMove objects into a continuous CameraAnchor table,\n    filling every hold gap between moves with unidirectional drift.\n    """\n    anchors: List[CameraAnchor] = []\n    lon_offset = 0.0\n    lat_offset = 0.0\n    scale_factor = 1.0\n\n    for i, mv in enumerate(moves):\n        mv.validate_duration()\n        if i > 0:\n            prev = moves[i - 1]\n            prev_end_t = prev.start_t + prev.duration\n            hold_dt = max(0.0, mv.start_t - prev_end_t)\n            if hold_dt > 0.0:\n                lon_offset += prev.drift_lon_rate * hold_dt\n                lat_offset += prev.drift_lat_rate * hold_dt\n                scale_factor *= math.exp(prev.drift_scale_rate * hold_dt)\n\n        s0 = float(np.clip(mv.span_start * scale_factor, 29.0, 168.0))\n        s1 = float(np.clip(mv.span_end * scale_factor, 29.0, 168.0))\n\n        if not anchors or mv.start_t > anchors[-1].t + 1e-3:\n            anchors.append(\n                CameraAnchor(\n                    t=mv.start_t,\n                    w=mv.w_start,\n                    lon=mv.lon_start + lon_offset,\n                    lat=mv.lat_start + lat_offset,\n                    span=s0,\n                    is_snap=mv.is_snap,\n                )\n            )\n        anchors.append(\n            CameraAnchor(\n                t=mv.start_t + mv.duration,\n                w=mv.w_end,\n                lon=mv.lon_end + lon_offset,\n                lat=mv.lat_end + lat_offset,\n                span=s1,\n                is_snap=mv.is_snap,\n            )\n        )\n    return anchors\n\n\ndef verify_retime_invariants(\n    original: List[LockedCameraMove], retimed: List[LockedCameraMove]\n) -> None:\n    """Asserts duration and peak velocity match within +-1 frame (1/60s) before and after retime."""\n    frame_tol = 1.0 / FPS\n    for orig, ret in zip(original, retimed):\n        if abs(orig.duration - ret.duration) > frame_tol:\n            raise AssertionError(\n                f"Retime duration violation on {orig.move_id}: "\n                f"{orig.duration:.4f}s vs {ret.duration:.4f}s"\n            )\n        if abs(orig.peak_zoom_velocity - ret.peak_zoom_velocity) > 1e-6:\n            raise AssertionError(\n                f"Retime peak velocity violation on {orig.move_id}: "\n                f"{orig.peak_zoom_velocity:.4f} vs {ret.peak_zoom_velocity:.4f}"\n            )\n'

# === pipeline/jt/show/moves.py ===
MODULES['pipeline/jt/show/moves.py'] = '"""\nJuicy Tea Map-Shorts Engine — 60fps Motion, Acceleration, Jerk & Event Pacing Linter.\nEnforces Sections 4.3, 4.4, 7, and 12.\n"""\n\nfrom __future__ import annotations\nfrom typing import Dict, List, Tuple\nimport math\nimport numpy as np\nfrom .camera import ContinuousCameraRig, FPS\n\n\ndef check_moves(\n    rig: ContinuousCameraRig,\n    snap_intervals: List[Tuple[float, float]] | None = None,\n) -> Dict[str, float | bool]:\n    """\n    Samples all 4 camera channels at 60 fps and enforces:\n    - No hard-clamping needed: w in [0, 1], span in [28, 170]\n    - Max zoom ratio per frame <= 1.02\n    - Max |d ln(span)/dt| <= 0.6/s normal, <= 1.2/s during snap-zoom\n    - Max pan speed <= 0.8 screen_widths/s\n    - Max |dw/dt| <= 1.2/s\n    - Max pan acceleration <= 2.0 screen_widths/s^2\n    - Max zoom acceleration |d^2 ln(span)/dt^2| <= 3.0/s^2\n    - Max frame-to-frame velocity step (jerk limit) <= 8% of peak move velocity\n    - Frame 0 starts in motion\n    """\n    snap_intervals = snap_intervals or []\n    n_frames = int(round(rig.total_duration * FPS))\n    dt = 1.0 / FPS\n\n    prev_state = None\n    max_span_ratio = 1.0\n    max_zoom_vel = 0.0\n    max_pan_vel = 0.0\n    max_dw = 0.0\n    max_pan_acc = 0.0\n    max_zoom_acc = 0.0\n\n    pan_vels: List[float] = []\n    zoom_vels: List[float] = []\n\n    for f in range(n_frames + 1):\n        t = f * dt\n        st = rig.evaluate_all(t)\n        w, span = st["w"], st["span"]\n\n        if not (-1e-3 <= w <= 1.001):\n            raise ValueError(f"w={w:.4f} out of [0,1] at t={t:.2f}s (fix anchors, do not clamp!)")\n        if not (28.0 <= span <= 170.0):\n            raise ValueError(f"span={span:.2f} out of [28,170] at t={t:.2f}s")\n\n        cos_lat = max(math.cos(math.radians(st["lat"])), 0.15)\n        vx_sw = (st["dlon"] * cos_lat) / span\n        vy_sw = st["dlat"] / span\n        pan_vel = math.hypot(vx_sw, vy_sw)\n\n        ax_sw = (st["ddlon"] * cos_lat) / span\n        ay_sw = st["ddlat"] / span\n        pan_acc = math.hypot(ax_sw, ay_sw)\n\n        zoom_vel = abs(st["dlog_span"])\n        zoom_acc = abs(st["ddlog_span"])\n        dw_vel = abs(st["dw"])\n\n        in_snap = any(s0 - 0.05 <= t <= s1 + 0.05 for s0, s1 in snap_intervals)\n        zoom_ceiling = 1.2 if in_snap else 0.6\n\n        if zoom_vel > zoom_ceiling + 1e-2:\n            raise ValueError(\n                f"Zoom velocity {zoom_vel:.3f}/s exceeds ceiling {zoom_ceiling}/s at t={t:.2f}s"\n            )\n        if pan_vel > 0.8 + 1e-2:\n            raise ValueError(f"Pan velocity {pan_vel:.3f} sw/s exceeds 0.8 sw/s at t={t:.2f}s")\n        if dw_vel > 1.2 + 1e-2:\n            raise ValueError(f"Morph speed |dw/dt|={dw_vel:.3f}/s exceeds 1.2/s at t={t:.2f}s")\n        if pan_acc > 2.0 + 2e-2:\n            raise ValueError(f"Pan accel {pan_acc:.3f} sw/s^2 exceeds 2.0 sw/s^2 at t={t:.2f}s")\n        if zoom_acc > 3.0 + 2e-2:\n            raise ValueError(f"Zoom accel {zoom_acc:.3f}/s^2 exceeds 3.0/s^2 at t={t:.2f}s")\n\n        if prev_state is not None:\n            s_ratio = max(span, prev_state["span"]) / min(span, prev_state["span"])\n            max_span_ratio = max(max_span_ratio, s_ratio)\n            if s_ratio > 1.02 + 1e-4:\n                raise ValueError(\n                    f"Frame span ratio {s_ratio:.4f} exceeds 1.02 limit at frame {f} (t={t:.2f}s)"\n                )\n\n        pan_vels.append(pan_vel)\n        zoom_vels.append(zoom_vel)\n        max_zoom_vel = max(max_zoom_vel, zoom_vel)\n        max_pan_vel = max(max_pan_vel, pan_vel)\n        max_dw = max(max_dw, dw_vel)\n        max_pan_acc = max(max_pan_acc, pan_acc)\n        max_zoom_acc = max(max_zoom_acc, zoom_acc)\n        prev_state = st\n\n    peak_pan = max(max_pan_vel, 0.05)\n    peak_zoom = max(max_zoom_vel, 0.05)\n    max_pan_step_pct = float(np.max(np.abs(np.diff(pan_vels))) / peak_pan)\n    max_zoom_step_pct = float(np.max(np.abs(np.diff(zoom_vels))) / peak_zoom)\n\n    if max_pan_step_pct > 0.08:\n        raise ValueError(f"Pan frame velocity step {max_pan_step_pct:.1%} > 8% ceiling (jerk spike).")\n    if max_zoom_step_pct > 0.08:\n        raise ValueError(f"Zoom frame velocity step {max_zoom_step_pct:.1%} > 8% ceiling (jerk spike).")\n\n    st0 = rig.evaluate_all(0.0)\n    if abs(st0["dlog_span"]) + abs(st0["dlon"]) + abs(st0["dlat"]) < 1e-3:\n        raise ValueError("Frame 0 is static! Video must start in motion.")\n\n    return {\n        "ok": True,\n        "max_span_ratio": round(max_span_ratio, 5),\n        "max_zoom_vel": round(max_zoom_vel, 4),\n        "max_pan_vel": round(max_pan_vel, 4),\n        "max_dw": round(max_dw, 4),\n        "max_pan_acc": round(max_pan_acc, 4),\n        "max_zoom_acc": round(max_zoom_acc, 4),\n        "max_pan_step_pct": round(max_pan_step_pct, 4),\n        "max_zoom_step_pct": round(max_zoom_step_pct, 4),\n    }\n\n\ndef check_event_pacing(\n    event_timestamps: List[float],\n    total_duration: float,\n    first_highlight_t: float,\n) -> Dict[str, float | bool]:\n    """\n    Enforces Section 7 Event Pacing Rules:\n    - First highlight in [0.0, 1.0s]\n    - Max gap between visual events <= 1.5s (drift does NOT count as an event)\n    - Target mean gap: 1.0 - 1.3s\n    """\n    if first_highlight_t > 1.0:\n        raise ValueError(f"First highlight at {first_highlight_t:.2f}s exceeds 1.0s rule.")\n\n    times = sorted(set([0.0] + [float(t) for t in event_timestamps] + [float(total_duration)]))\n    gaps = np.diff(times)\n    max_gap = float(np.max(gaps)) if len(gaps) > 0 else total_duration\n    mean_gap = float(np.mean(gaps)) if len(gaps) > 0 else total_duration\n\n    if max_gap > 1.5 + 1e-6:\n        bad_idx = int(np.argmax(gaps))\n        raise ValueError(\n            f"Dead event window of {max_gap:.2f}s (> 1.5s limit) between "\n            f"t={times[bad_idx]:.2f}s and t={times[bad_idx + 1]:.2f}s."\n        )\n\n    return {\n        "ok": True,\n        "max_event_gap_s": round(max_gap, 3),\n        "mean_event_gap_s": round(mean_gap, 3),\n        "event_count": len(event_timestamps),\n    }\n'

# === pipeline/jt/show/vfx_core.py ===
MODULES['pipeline/jt/show/vfx_core.py'] = '"""\nJuicy Tea Map-Shorts Engine — C2-Continuous VFX Curves (Icon Pop, Label Pop & Moving Fade-Out).\nNote: During holds, the camera maintains continuous unidirectional drift (Rule 4).\n"""\n\nfrom __future__ import annotations\nfrom typing import Tuple\nfrom .camera import smootherstep\n\n\ndef icon_pop_scale(elapsed_s: float, duration_s: float = 0.60, peak: float = 1.15) -> float:\n    """\n    C2-continuous easeOutBack curve reaching 115% peak over 0.60s (36 frames @ 60fps)\n    and settling smoothly to 100% with zero velocity break at the peak.\n    Replaces the broken linear-ramp + smoothstep icon_pop (Section 11.2 #6).\n    """\n    if elapsed_s <= 0.0:\n        return 0.0\n    if elapsed_s >= duration_s:\n        return 1.0\n    # Two quintic smoothersteps joined at the peak. Each piece has zero velocity\n    # and zero acceleration at its ends, so the 115% crest is C2 — no velocity break.\n    peak_at = 0.62 * duration_s\n    if elapsed_s <= peak_at:\n        return float(peak * smootherstep(elapsed_s / peak_at))\n    settle = (elapsed_s - peak_at) / (duration_s - peak_at)\n    return float(peak + (1.0 - peak) * smootherstep(settle))\n\n\ndef label_pop_state(elapsed_s: float, duration_s: float = 0.30) -> Tuple[float, float]:\n    """\n    Section 6.1 Label Pop: 0.25-0.35s, <= 8% overshoot (1.06), smootherstep alpha in first 60%.\n    """\n    if elapsed_s <= 0.0:\n        return 0.0, 0.0\n    if elapsed_s >= duration_s:\n        return 1.0, 1.0\n    scale = icon_pop_scale(elapsed_s, duration_s=duration_s, peak=1.06)\n    alpha = float(smootherstep(min(1.0, elapsed_s / (0.60 * duration_s))))\n    return scale, alpha\n\n\ndef element_fade_and_exit_offset(\n    t: float,\n    enter_t: float,\n    exit_t: float,\n    fade_in_s: float = 0.28,\n    fade_out_s: float = 0.28,\n    exit_drift_px: Tuple[float, float] = (18.0, -12.0),\n) -> Tuple[float, float, float]:\n    """\n    Enforces >= 0.25s smooth fade-in/out and keeps exiting elements moving for >= 0.40s\n    so no element freezes before vanishing or disappears in 1 frame.\n    Returns (alpha, dx_px, dy_px).\n    """\n    fade_in_s = max(fade_in_s, 0.25)\n    fade_out_s = max(fade_out_s, 0.25)\n    exit_move_s = max(fade_out_s, 0.40)\n\n    if t <= enter_t or t >= exit_t + fade_out_s:\n        return 0.0, 0.0, 0.0\n    if t < enter_t + fade_in_s:\n        alpha = float(smootherstep((t - enter_t) / fade_in_s))\n        return alpha, 0.0, 0.0\n    if t > exit_t:\n        u_fade = min(1.0, (t - exit_t) / fade_out_s)\n        u_move = min(1.0, (t - exit_t) / exit_move_s)\n        alpha = float(1.0 - smootherstep(u_fade))\n        s_move = float(smootherstep(u_move))\n        return alpha, exit_drift_px[0] * s_move, exit_drift_px[1] * s_move\n    return 1.0, 0.0, 0.0\n'

# === pipeline/jt/show/truesize.py ===
MODULES['pipeline/jt/show/truesize.py'] = '"""\nJuicy Tea Map-Shorts Engine — True-Size Country Drag Module (Rule 8, Rule 9 & Section 6.2).\n"""\n\nfrom __future__ import annotations\nfrom typing import Dict, Tuple\nimport math\nimport numpy as np\nfrom .camera import smootherstep\n\n\ndef truesize_drag_state(\n    t: float,\n    start_t: float,\n    duration_s: float,\n    start_lon_lat: Tuple[float, float],\n    end_lon_lat: Tuple[float, float],\n    ref_lat: float,\n) -> Dict[str, float | str | bool]:\n    """\n    Section 6.2 True-Size Drag:\n    - Smootherstep path over 1.2 - 2.0s (peak velocity at midpoint, zero spring bounce).\n    - Continuous sec^2(lat) area scaling recalculated on every frame.\n    - Fixed format f"{mult:.1f}x" counter string so width never jumps.\n    - Kenney SVG hand prop parallax timestamp at t - 1/30s without dark shadow circle.\n    """\n    duration_s = float(np.clip(duration_s, 1.2, 2.0))\n    u = float(np.clip((t - start_t) / duration_s, 0.0, 1.0))\n    s = float(smootherstep(u))\n\n    lon = start_lon_lat[0] + s * (end_lon_lat[0] - start_lon_lat[0])\n    lat = start_lon_lat[1] + s * (end_lon_lat[1] - start_lon_lat[1])\n\n    cos_ref = max(math.cos(math.radians(ref_lat)), 0.05)\n    cos_cur = max(math.cos(math.radians(lat)), 0.05)\n    linear_scale = cos_ref / cos_cur\n    area_mult = (cos_cur / cos_ref) ** 2\n\n    return {\n        "lon": lon,\n        "lat": lat,\n        "linear_scale": linear_scale,\n        "counter_text": f"{area_mult:.1f}x",\n        "hand_parallax_t": max(0.0, t - (1.0 / 30.0)),\n        "draw_hand_shadow_circle": False,\n    }\n'

# === pipeline/jt/show/pack.py ===
MODULES['pipeline/jt/show/pack.py'] = '"""\nJuicy Tea Map-Shorts Engine — Coastline-Mask Packing & Puzzle-Fit Module (Rule 9 & Section 6.3).\n"""\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Tuple\nimport numpy as np\nfrom .camera import smootherstep\n\n\n@dataclass(frozen=True)\nclass PackedPiece:\n    country_id: str\n    start_xy: Tuple[float, float]\n    target_xy: Tuple[float, float]\n    enter_t: float\n    move_duration: float = 0.80  # 0.6 - 1.0s smootherstep arrival\n    rotation_deg: float = 0.0    # 0.0 for puzzle-fit comparisons\n\n\ndef evaluate_packed_pieces(\n    pieces: List[PackedPiece],\n    t: float,\n    stagger_s: float = 0.22,\n) -> List[Dict[str, float | str]]:\n    """\n    Section 6.3 Packing & Puzzle-Fit:\n    Each piece arrives individually over 0.6-1.0s on a smootherstep trajectory\n    with 0.15-0.30s stagger, zero rotation for puzzle-fit comparisons.\n    """\n    stagger_s = float(np.clip(stagger_s, 0.15, 0.30))\n    states = []\n    for idx, p in enumerate(pieces):\n        t0 = p.enter_t + idx * stagger_s\n        dur = float(np.clip(p.move_duration, 0.60, 1.00))\n        if t < t0:\n            continue\n        u = float(np.clip((t - t0) / dur, 0.0, 1.0))\n        s = float(smootherstep(u))\n        x = p.start_xy[0] + s * (p.target_xy[0] - p.start_xy[0])\n        y = p.start_xy[1] + s * (p.target_xy[1] - p.start_xy[1])\n        alpha = float(smootherstep(min(1.0, (t - t0) / 0.28)))\n        states.append({\n            "country_id": p.country_id,\n            "x": x,\n            "y": y,\n            "alpha": alpha,\n            "rotation_deg": 0.0,\n        })\n    return states\n'

# === pipeline/jt/show/polys.py ===
MODULES['pipeline/jt/show/polys.py'] = '"""\nJuicy Tea Map-Shorts Engine — True Coastline & Horizon-Arc Polygon Clipping (Section 5).\n"""\n\nfrom __future__ import annotations\nfrom typing import List, Tuple\nimport math\nimport numpy as np\n\n\ndef clip_polygon_to_globe_rim(\n    pts_xy: np.ndarray,\n    visible_mask: np.ndarray,\n    globe_center: Tuple[float, float],\n    globe_radius: float,\n) -> np.ndarray:\n    """\n    Section 5 Coastline Fill Rule:\n    Never chord-closes a half-clipped globe rim or viewport-clipped polygon.\n    Replaces horizon crossings with smooth circular arc points along the true globe rim.\n    """\n    if np.all(visible_mask):\n        return pts_xy\n    if not np.any(visible_mask):\n        return np.zeros((0, 2), dtype=np.float64)\n\n    cx, cy = globe_center\n    out: List[np.ndarray] = []\n    n = len(pts_xy)\n\n    for i in range(n):\n        if visible_mask[i]:\n            out.append(pts_xy[i])\n            nxt = (i + 1) % n\n            if not visible_mask[nxt]:\n                j = nxt\n                while not visible_mask[j] and j != i:\n                    j = (j + 1) % n\n                a0 = math.atan2(pts_xy[i, 1] - cy, pts_xy[i, 0] - cx)\n                a1 = math.atan2(pts_xy[j, 1] - cy, pts_xy[j, 0] - cx)\n                da = ((a1 - a0 + math.pi) % (2.0 * math.pi)) - math.pi\n                arc_angles = np.linspace(a0, a0 + da, 16)\n                for ang in arc_angles[1:-1]:\n                    out.append(\n                        np.array([cx + globe_radius * math.cos(ang), cy + globe_radius * math.sin(ang)])\n                    )\n\n    return np.asarray(out, dtype=np.float64) if out else np.zeros((0, 2), dtype=np.float64)\n'

# === pipeline/jt/captions.py ===
MODULES['pipeline/jt/captions.py'] = '"""\nJuicy Tea Map-Shorts Engine — Skia Cyan (#00E5FF) Karaoke & Stroked Caption Renderer.\nEnforces Rule 9 & Section 6.4:\n- Bold white sans-serif with dark stroke, glyph >= 64px, in 64-72% height band.\n- Active word switches 0.04s early to Cyan #00E5FF whenever yellow exists on map.\n- Safe zones: top 12% (y<230), bottom 20% (y>1536), and x>900 remain empty.\n"""\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import List, Tuple\n\ntry:\n    import skia\nexcept ImportError:\n    skia = None\n\nKARAOKE_ACTIVE_CYAN: Tuple[int, int, int, int] = (0, 229, 255, 255)   # #00E5FF\nKARAOKE_INACTIVE_WHITE: Tuple[int, int, int, int] = (255, 255, 255, 255)\nSTROKE_DARK: Tuple[int, int, int, int] = (14, 18, 26, 245)\n\n\n@dataclass(frozen=True)\nclass KaraokeWord:\n    text: str\n    start: float\n    end: float\n\n\ndef active_karaoke_style(\n    words: List[KaraokeWord],\n    t: float,\n    map_has_yellow: bool = True,\n    lead_s: float = 0.04,\n) -> List[Tuple[str, Tuple[int, int, int, int]]]:\n    """Switches active word highlight 0.04s early to Cyan #00E5FF."""\n    t_shifted = t + lead_s\n    active_color = KARAOKE_ACTIVE_CYAN if map_has_yellow else (255, 214, 10, 255)\n    return [\n        (w.text, active_color if (w.start <= t_shifted <= w.end) else KARAOKE_INACTIVE_WHITE)\n        for w in words\n    ]\n\n\ndef draw_skia_karaoke_caption(\n    canvas: "skia.Canvas",\n    active_line_words: List[KaraokeWord],\n    t: float,\n    map_has_yellow: bool = True,\n) -> None:\n    """Renders >= 64px bold stroked captions in the 64-72% height band (y = 1228..1382)."""\n    if skia is None or not active_line_words:\n        return\n\n    styled = active_karaoke_style(active_line_words, t, map_has_yellow=map_has_yellow)\n    font_size = 68.0\n    typeface = skia.Typeface.MakeFromName("Inter", skia.FontStyle.Bold())\n    font = skia.Font(typeface, font_size)\n\n    space_w = font.measureText(" ")\n    word_widths = [font.measureText(w_text) for w_text, _ in styled]\n    total_w = sum(word_widths) + space_w * max(0, len(styled) - 1)\n\n    safe_center_x = 480.0\n    start_x = max(80.0, min(safe_center_x - 0.5 * total_w, 880.0 - total_w))\n    baseline_y = 1310.0\n\n    stroke_paint = skia.Paint(\n        AntiAlias=True,\n        Style=skia.Paint.kStroke_Style,\n        StrokeWidth=11.0,\n        StrokeJoin=skia.Paint.kRound_Join,\n        Color=skia.Color(*STROKE_DARK),\n    )\n\n    cursor_x = start_x\n    for (w_text, rgba), ww in zip(styled, word_widths):\n        fill_paint = skia.Paint(\n            AntiAlias=True,\n            Style=skia.Paint.kFill_Style,\n            Color=skia.Color(*rgba),\n        )\n        canvas.drawSimpleText(w_text, cursor_x, baseline_y, font, stroke_paint)\n        canvas.drawSimpleText(w_text, cursor_x, baseline_y, font, fill_paint)\n        cursor_x += ww + space_w\n'

